Lemma csk_kept (R1 R2 : bvmap 5 word) KS : (forall j, In j CSK -> In j KS) -> (forall x, In x KS -> getr R2 (reg x) = getr R1 (reg x)) ->
  (forall j, In j CSK -> getr R1 (reg j) = getr R (reg j)) -> forall j, In j CSK -> getr R2 (reg j) = getr R (reg j).
Proof.
